import { createFileRoute, lazyRouteComponent } from "@tanstack/react-router";
import { fallback, zodValidator } from "@tanstack/zod-adapter";
import { z } from "zod";
//#region src/routes/programs.tsx
var $$splitComponentImporter = () => import("./programs-CknFlmLU.js");
var searchSchema = z.object({
	search: fallback(z.string(), "").default(""),
	country: fallback(z.string(), "").default(""),
	level: fallback(z.string(), "").default(""),
	topic: fallback(z.string(), "").default(""),
	sortBy: fallback(z.enum([
		"university",
		"country",
		"level"
	]), "university").default("university"),
	sortOrder: fallback(z.enum(["asc", "desc"]), "asc").default("asc")
});
var Route = createFileRoute("/programs")({
	validateSearch: zodValidator(searchSchema),
	loader: async () => {
		let programs = [];
		let topics = null;
		try {
			const programsResponse = await fetch("/data/programs.json");
			if (programsResponse.ok) {
				programs = await programsResponse.json();
				console.log(`[programs] loaded ${programs.length} programs`);
			}
		} catch (error) {
			console.error("[programs] failed to load programs.json:", error);
		}
		try {
			const topicsResponse = await fetch("/data/topics.json");
			if (topicsResponse.ok) {
				topics = await topicsResponse.json();
				console.log(`[programs] loaded topics`);
			}
		} catch (error) {
			console.error("[programs] failed to load topics.json:", error);
		}
		return {
			programs,
			topics
		};
	},
	component: lazyRouteComponent($$splitComponentImporter, "component")
});
//#endregion
export { Route as t };
